package com.mantou.salesdialer.contacts;
import android.app.Activity;import android.os.Bundle;import android.util.AtomicFile;import android.widget.TextView;import java.io.*;import java.time.*;import java.util.*;import org.json.JSONObject;
import com.mantou.salesdialer.contacts.WorkspaceTimerModel.Ticket;
/** Isolated deterministic tests. Ignores all Intent extras, never opens the user's workspace. */
public final class WorkspaceTimerCheckActivity extends Activity {
 int checks;void check(boolean ok){checks++;if(!ok)throw new IllegalStateException("TIMER_ASSERTION_"+checks);}void denied(Runnable r,String message){checks++;try{r.run();}catch(RuntimeException e){if(message.equals(e.getMessage()))return;throw new IllegalStateException("UNEXPECTED_"+e.getMessage(),e);}throw new IllegalStateException("EXPECTED_"+message);}
 static final long NOW=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli();
 static final class Time implements SyntheticTaskLoop.Time{long wall=NOW,elapsed=1000;String boot="TEST-BOOT";public Clock wall(){return Clock.fixed(Instant.ofEpochMilli(wall),ZoneOffset.UTC);}public long elapsedMillis(){return elapsed;}public String bootId(){return boot;}void advance(long n){wall+=n;elapsed+=n;}}
 static final class Tickets implements WorkspaceTimerCoordinator.Tickets{Ticket current;boolean fail;public Ticket read(){return current;}public void write(Ticket t){if(fail)throw new IllegalStateException("TICKET_WRITE_FAILED");current=t;}}
 static final class Alarm implements WorkspaceTimerCoordinator.Alarm{boolean permitted=true,fail;int arms,cancels;public void ready(){if(!permitted)throw new IllegalStateException("EXACT_ALARM_REQUIRED");}public void arm(Ticket t){if(fail)throw new IllegalStateException("ARM_FAILED");arms++;}public void cancel(){cancels++;}}
 final class Fixture implements AutoCloseable {final String name="workspace-fixture-"+UUID.randomUUID().toString().replace("-","")+".db";final ContactTaskStore store=ContactTaskStore.workspaceFixture(WorkspaceTimerCheckActivity.this,name,p->{});final Time time=new Time();final Tickets tickets=new Tickets();final Alarm alarm=new Alarm();final SyntheticTaskLoop.RecordingPort port=new SyntheticTaskLoop.RecordingPort(SyntheticTaskLoop.RecordingPort.Mode.ACK);final WorkspaceTimerCoordinator timer=new WorkspaceTimerCoordinator(store,time,tickets,alarm,port);final SyntheticWorkspaceSession session=new SyntheticWorkspaceSession(store,time);Fixture(){session.importIds("SIM-061\nSIM-062");}SyntheticWorkspaceSession.Row row(){return session.view().contacts.get(0);}void arrange(){timer.arrange(row(),store.getPlan().version,time.wall+30000);}public void close(){session.close();}}
 void runChecks()throws Exception{
  try(Fixture f=new Fixture()){f.arrange();Ticket first=f.tickets.current;check(f.alarm.arms==1&&!f.store.getPlan().paused);check(f.timer.fire(first.version-1,first.token).equals("STALE_TIMER")&&f.tickets.current==first);f.time.advance(30000);check(f.timer.fire(first.version,first.token).equals("SIMULATED_API_RECEIVED"));check(f.port.requests().size()==1&&f.session.view().counters.pending==1);check(f.timer.fire(first.version,first.token).equals("STALE_TIMER")&&f.port.requests().size()==1);}
  try(Fixture f=new Fixture()){f.arrange();Ticket first=f.tickets.current;f.arrange();Ticket next=f.tickets.current;check(f.timer.fire(first.version,first.token).equals("STALE_TIMER")&&f.tickets.current==next);f.timer.recover();check(f.store.getPlan().paused&&f.tickets.current==null);f.time.advance(30000);check(f.timer.fire(next.version,next.token).equals("STALE_TIMER")&&f.port.requests().isEmpty());}
  try(Fixture f=new Fixture()){f.arrange();Ticket t=f.tickets.current;f.store.refuse(f.row().contact.id,1);f.time.advance(30000);denied(()->f.timer.fire(t.version,t.token),"STALE_CONTACT");check(f.port.requests().isEmpty()&&f.store.getPlan().paused&&f.tickets.current==null);}
  try(Fixture f=new Fixture()){f.arrange();Ticket t=f.tickets.current;f.time.advance(60001);check(f.timer.fire(t.version,t.token).equals("EXPIRED")&&f.store.getPlan().paused&&f.port.requests().isEmpty());}
  try(Fixture f=new Fixture()){f.arrange();Ticket t=f.tickets.current;f.time.advance(30000);f.time.boot="NEW";check(f.timer.fire(t.version,t.token).equals("TIMER_CLOCK_CHANGED")&&f.port.requests().isEmpty());}
  try(Fixture f=new Fixture()){f.alarm.permitted=false;denied(f::arrange,"EXACT_ALARM_REQUIRED");check(f.store.getPlan().version==0&&f.tickets.current==null);f.alarm.permitted=true;f.alarm.fail=true;denied(f::arrange,"ARM_FAILED");check(f.store.getPlan().paused&&f.tickets.current==null&&f.port.requests().isEmpty());}
  try(Fixture f=new Fixture()){f.arrange();Ticket t=f.tickets.current;f.time.advance(30000);f.tickets.fail=true;denied(()->f.timer.fire(t.version,t.token),"TICKET_WRITE_FAILED");check(f.port.requests().isEmpty()&&f.store.getPlan().paused&&f.session.view().counters.attempts==0);f.tickets.fail=false;f.timer.recover();}
  File path=new File(getFilesDir(),"workspace-ticket-fixture-"+UUID.randomUUID()+".bin");WorkspaceTimerRuntime.TicketFile file=new WorkspaceTimerRuntime.TicketFile(path);Ticket t=new Ticket(1,NOW+30000,31000,"TEST-BOOT","a".repeat(32));file.write(t);check(file.read().version==1&&file.read().token.equals(t.token));file.write(null);check(file.read()==null);try(FileOutputStream out=new FileOutputStream(path)){out.write(new byte[]{1,2,3});}denied(file::read,"TIMER_FILE_INVALID");check(path.length()==3);
 }
 @Override public void onCreate(Bundle saved){super.onCreate(saved);TextView view=new TextView(this);view.setText("正在检查隔离合成定时器，不拨电话。");setContentView(view);new Thread(()->{JSONObject j=new JSONObject();boolean ok=false;try{runChecks();j.put("decision","PASSED");ok=true;}catch(Exception e){try{j.put("decision","FAILED").put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){}}try{j.put("tests","T646-T649").put("assertions",checks).put("actualPhoneCalls",0).put("userWorkspaceOpened",false);AtomicFile file=new AtomicFile(new File(getFilesDir(),"workspace-timer-check.json"));FileOutputStream out=file.startWrite();out.write(j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception ignored){ok=false;}boolean passed=ok;runOnUiThread(()->view.setText(passed?"隔离定时规则通过":"隔离定时规则未通过"));},"workspace-timer-fixture").start();}
}
